def transforms(p):
 a=np.array([list(s) for s in p]);out={}
 for k in range(4):
  r=np.rot90(a,k);out[f'r{k*90}']=tuple(''.join(row) for row in r)
  f=np.fliplr(r);out[f'r{k*90}f']=tuple(''.join(row) for row in f)
 return out
